	}

	missingUsersByID, err := s.listUsersByID(ctx, missingUserIDs)
	if err != nil {
		return nil, err
	}
	for userID, user := range missingUsersByID {
		if user != nil {
			usersByID[userID] = user
		}
	}
	return usersByID, nil
}

